WITH with_dims AS (SELECT s.*, e.level AS employee_level, e.full_name AS employee_full_name, e.salary AS employee_salary FROM employees s LEFT JOIN employees e ON s.manager_id <=> e.id), enriched AS (SELECT *, COUNT(employee_salary) OVER w_ordered AS last4_count_employee_salary, AVG(employee_salary) OVER w_ordered AS last4_avg_employee_salary, MAX(employee_salary) OVER w_ordered AS last4_max_employee_salary, NTILE(4) OVER (ORDER BY salary DESC, id) AS salary_bucket FROM with_dims WHERE job_title IN ('Analyst', 'Intern', 'Designer') WINDOW w_ordered AS (PARTITION BY manager_id, job_title ORDER BY salary, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)), kept_keys AS (SELECT job_title, dept_id FROM enriched EXCEPT ALL SELECT job_title, dept_id FROM employees WHERE is_remote = FALSE), kept_rows AS (SELECT s.* FROM enriched s JOIN kept_keys k ON s.job_title = k.job_title AND s.dept_id = k.dept_id), remaining_keys AS (SELECT id FROM kept_rows EXCEPT SELECT id FROM employees WHERE level IN ('L4', 'L3')), verified AS (SELECT s.* FROM kept_rows s JOIN remaining_keys k ON s.id = k.id), enriched_employees AS (SELECT e.id, e.full_name, e.email, e.dept_id, e.manager_id, e.job_title, e.hire_date, e.employee_level, e.employee_salary, e.last4_count_employee_salary, e.last4_avg_employee_salary, e.last4_max_employee_salary, d.salary AS employee_salary_2, d.hire_date AS employee_hire_date FROM verified e LEFT JOIN employees d ON e.manager_id <=> d.id), daily AS (SELECT DATE_TRUNC('YEAR', employee_hire_date) AS year_start, manager_id, COUNT(DISTINCT manager_id) AS distinct_manager_ids, APPROX_PERCENTILE(employee_salary_2, 0.5) AS employee_salary_2_p50, SORT_ARRAY(COLLECT_SET(job_title)) AS job_title_list, SORT_ARRAY(COLLECT_SET(job_title)) AS job_title_list_2, GROUPING_ID() AS grouping_level FROM enriched_employees GROUP BY CUBE (DATE_TRUNC('YEAR', employee_hire_date), manager_id)) SELECT distinct_manager_ids, employee_salary_2_p50, job_title_list, job_title_list_2, grouping_level FROM daily ORDER BY grouping_level DESC;
